1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
8	 * region code derived from the postcode (NSW/VIC/QLD, else {@code UNKNOWN}) and HASH8 is the first 8
9	 * upper-case hex characters of SHA-256 over {@code normalizedTelephone + lastName} (e.g.
10	 * {@code NSW-1A2B3C4D}). There are no sequence numbers: the code is fully determined by the owner's
11	 * region and hashed identity.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner) {
16	        String region = OwnerRegion.fromPostcode(owner.getPostcode());
17	        if (region == null) {
18	            region = "UNKNOWN";
19	        }
20	        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
21	        owner.setCustomerCode(region + "-" + hash8);
22	    }
23	}
