1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * The single source of truth for an owner's derived {@code identityKey} and its parts. All duplicate
11	 * detection is now expressed through this one key:
12	 *
13	 * <pre>identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId</pre>
14	 *
15	 * <p>Two owners are duplicates only when their <em>whole</em> identityKey is equal. Because the
16	 * telephone is part of the key, two members of the same household (same householdId) with different
17	 * telephones have different identityKeys and are both allowed; only an exact full-key match is a
18	 * duplicate.
19	 *
20	 * <p>The household component is the deterministic id derived from the normalized lastName and postcode
21	 * (see {@link #deriveHouseholdId}).
22	 */
23	public final class OwnerIdentity {
24	
25	    private OwnerIdentity() {
26	    }
27	
28	    /**
29	     * The identityKey from its already-known parts. Telephone is canonicalized to E.164 and email is
30	     * lower-cased so differing formats or case do not hide a match; a null household is the empty
31	     * string.
32	     */
33	    public static String key(String telephone, String email, String householdId) {
34	        return canonicalTelephone(telephone) + '|' + normalizedEmail(email) + '|'
35	                + (householdId == null ? "" : householdId);
36	    }
37	
38	    /**
39	     * The E.164 form used for comparison. A value that is already E.164 is returned unchanged; a value
40	     * that predates E.164 storage is normalized on the fly, falling back to its bare digits if it
41	     * cannot form valid E.164.
42	     */
43	    public static String canonicalTelephone(String value) {
44	        try {
45	            return OwnerTelephone.toE164(value);
46	        }
47	        catch (InvalidTelephoneException ex) {
48	            return value == null ? "" : value.replaceAll("\\D", "");
49	        }
50	    }
51	
52	    /** The email lower-cased and trimmed, or the empty string when null or blank. */
53	    public static String normalizedEmail(String value) {
54	        if (value == null || value.isBlank()) {
55	            return "";
56	        }
57	        return value.trim().toLowerCase();
58	    }
59	
60	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
61	    public static String normalizeName(String value) {
62	        if (value == null) {
63	            return "";
64	        }
65	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
66	    }
67	
68	    /**
69	     * The deterministic household id: the first 12 hex characters of SHA-256 over
70	     * {@code normalizedLastName + '|' + postcode}. Owners with the same normalized lastName and
71	     * postcode therefore resolve to the same value automatically, so the household is keyed on
72	     * (lastName, postcode). A null postcode is treated as the empty string.
73	     */
74	    public static String deriveHouseholdId(String normalizedLastName, String postcode) {
75	        return sha256Hex(normalizedLastName + '|' + (postcode == null ? "" : postcode), 12);
76	    }
77	
78	    /**
79	     * HASH8: the first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
80	     * lastName}, where the telephone is canonicalized to E.164. This is the hashed component of the
81	     * owner's {@code customerCode} ({@code <REGION>-<HASH8>}).
82	     */
83	    public static String customerHash(String telephone, String lastName) {
84	        return sha256Hex(canonicalTelephone(telephone) + (lastName == null ? "" : lastName), 8);
85	    }
86	
87	    /**
88	     * The first {@code hexChars} upper-case hex characters of SHA-256 over the UTF-8 bytes of
89	     * {@code input} — the shared primitive behind every hash-derived identity part.
90	     */
91	    static String sha256Hex(String input, int hexChars) {
92	        try {
93	            byte[] digest = MessageDigest.getInstance("SHA-256")
94	                    .digest(input.getBytes(StandardCharsets.UTF_8));
95	            StringBuilder sb = new StringBuilder(hexChars);
96	            for (byte b : digest) {
97	                sb.append(String.format("%02X", b));
98	                if (sb.length() >= hexChars) {
99	                    break;
100	                }
101	            }
102	            return sb.substring(0, hexChars);
103	        }
104	        catch (NoSuchAlgorithmException ex) {
105	            throw new IllegalStateException("SHA-256 not available", ex);
106	        }
107	    }
108	}
