3	import org.junit.jupiter.api.Test;
4	import static org.junit.jupiter.api.Assertions.assertNotEquals;
5	
6	/** code-collision: on a customerCode collision, append '-&lt;n&gt;' (smallest n &gt;= 2) to keep it
7	 * unique. A genuine hash collision cannot be forced black-box (it needs an identical
8	 * normalizedTelephone + lastName, which telephone-uniqueness already blocks), so assert the rule's
9	 * guarantee instead: distinct owners always get distinct customerCodes. */
10	class AcceptanceTest extends AcceptanceBase {
11	
12		@Test
13		void coreCustomerCodesStayUnique() throws Exception {
14			String c1 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
15			String c2 = fetchOwner(createOwnerOk(withPostcode(ownerNode()))).get("customerCode").asText();
16			assertNotEquals(c1, c2);
17		}
18	}
